with recent_products as (select *, upper(trim(product_name)) as product_name_normalized from products where array_contains(tags, 'bestseller')), category_summary as (select category, case when stock_qty >= 300 then 'high' when stock_qty >= 51 then 'mid' else 'low' end as stock_qty_bucket, count(distinct stock_qty) as unique_categorys, min(cost) as min_cost from recent_products group by category, case when stock_qty >= 300 then 'high' when stock_qty >= 51 then 'mid' else 'low' end) select * from category_summary;
